def solve_quadratic_equation(a, b, c):
    D = b**2 - 4*a*c
    if D < 0:
        return "Уравнение не имеет решений."
    elif D == 0:
        x = -b / (2*a)
        return f"Уравнение имеет один корень: x = {x}"
    else:
        x1 = (-b + (D ** 0.5)) / (2*a)
        x2 = (-b - (D ** 0.5)) / (2*a)
        return f"Уравнение имеет два корня: x1 = {x1}, x2 = {x2}"
